const body = $json.body || $json;

const message = body.message || body.prompt || 'Say hello from Agentics.';
const model = body.model || 'agentics-assistant:latest';

const payload = {
  model: model,
  prompt: message,
  stream: false,
  options: {
    temperature: Number(body.temperature || 0.4),
    num_ctx: Number(body.num_ctx || 4096),
    num_predict: Number(body.num_predict || 512)
  }
};

const response = await fetch('http://ollama:11434/api/generate', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(payload)
});

const text = await response.text();

if (!response.ok) {
  return [{ json: { ok: false, source: 'ollama', status: response.status, error: text } }];
}

const data = JSON.parse(text);

return [{ json: { ok: true, source: 'n8n-agentics-chat-v2', model: data.model, response: data.response, eval_count: data.eval_count, prompt_eval_count: data.prompt_eval_count, total_duration: data.total_duration } }];
